// Chat AI - frontend, 26 Oct 2026: descriptions for the 4 tag-2610 image style titles. Written only where the live description is empty.
const DESCS = {
  "965509844": "Landing page, 'Image styles' section: title on a style card showing a photo turned into a portrait painted in watercolor by the AI image generator. Short card title: no final period, use your language's capitalization (no English title case), keep about as short as the English.",
  "965509845": "Landing page, 'Image styles' section: title on a style card showing a photo converted into a black-and-white (single-colour) image by the AI image generator. Short card title: no final period, use your language's capitalization (no English title case), keep about as short as the English.",
  "965509846": "Landing page, 'Image styles' section: title on a style card showing a photo turned into a chibi illustration (Japanese anime/manga style with a small body and an oversized head) by the AI image generator. 'Chibi' is normally kept as is. Short card title: no final period.",
  "965509847": "Landing page, 'Image styles' section: title on a style card for the style that shows the person's face with suggested makeup looks (AI makeup suggestions/try-on). 'Guide' means suggestions/how-to, not a person. Short card title: no final period, use your language's capitalization (no English title case), keep about as short as the English."
};
return [{ json: { project_id: '691331356a3b9a68428ab3.43540470', descs: DESCS, key_ids: Object.keys(DESCS) } }];

// Guards: skip archived; description written only where the live description is empty (never overwrite an existing one).
const p = $('Params').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const out = []; const skipped = []; const before = [];
for (const id of p.key_ids) {
  const k = byId[id]; if (!k || k.is_archived) { skipped.push({ id: id, why: 'missing/archived' }); continue; }
  before.push({ id: k.key_id, description: k.description || '' });
  if (String(k.description || '').trim()) { skipped.push({ id: id, why: 'description already set', now: k.description }); continue; }
  out.push({ key_id: Number(id), description: p.descs[id] });
}
if (out.length === 0) { throw new Error('Nothing to write: ' + JSON.stringify(skipped)); }
return [{ json: { body: { keys: out }, skipped: skipped, before: before, plan: out.map(function (x) { return x.key_id; }) } }];

const p = $('Params').first().json; const B = $('Build').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const res = B.plan.map(function (id) { const k = byId[id] || {}; return { id: id, ok: k.description === p.descs[String(id)], description: k.description, tags: k.tags }; });
const bad = res.filter(function (x) { return !x.ok; });
return [{ json: { ok: bad.length === 0, results: res, skipped: B.skipped, bad: bad } }];

// Lokalise returned 500 on a 40-key PUT: send 10 keys per call.
const out = [];
for (const it of $input.all()) { const ks = it.json.body.keys; for (let i = 0; i < ks.length; i += 10) { out.push({ json: { body: { keys: ks.slice(i, i + 10) } } }); } }
return out;
